// Every channel names the same thing differently. Normalising here is what lets one
// creative score compare a LinkedIn post against a TikTok video against an email.
const m = $json.metrics || {};
const pick = (...k) => { for (const x of k) if (m[x] != null) return Number(m[x]); return null; };
const impressions = pick('impressions', 'views', 'reach', 'plays', 'delivered');
const engagements = pick('engagements', 'likes', 'reactions', 'total_interactions');
const clicks = pick('clicks', 'link_clicks', 'unique_clicks', 'website_clicks');
const conversions = pick('conversions', 'purchases', 'leads', 'bookings');
return [{ json: {
  publication_id: $json.publication_id,
  asset_ids: $json.asset_ids || [],
  channel: $json.channel,
  impressions, engagements, clicks, conversions,
  spend_minor_units: pick('spend', 'cost') ?? 0,
  engagement_rate: impressions ? (engagements ?? 0) / impressions : null,
  ctr: impressions ? (clicks ?? 0) / impressions : null,
  cvr: clicks ? (conversions ?? 0) / clicks : null,
  watch_through_rate: m.video_views_p100 && m.plays ? m.video_views_p100 / m.plays : null,
  collected_at: new Date().toISOString()
} }];
